import{_ as a,o as n,c as e,a2 as t}from"./chunks/framework.XXezeKOl.js";const u=JSON.parse('{"title":"MCP 架构与核心概念","description":"理解 Model Context Protocol 的 Host / Client / Server 三角色、三类能力原语、两种传输方式和底层的 JSON-RPC 消息。","frontmatter":{"title":"MCP 架构与核心概念","description":"理解 Model Context Protocol 的 Host / Client / Server 三角色、三类能力原语、两种传输方式和底层的 JSON-RPC 消息。"},"headers":[],"relativePath":"guide/10-mcp/mcp-overview.md","filePath":"guide/10-mcp/mcp-overview.md","lastUpdated":null}'),i={name:"guide/10-mcp/mcp-overview.md"};function l(r,s,p,o,d,c){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="mcp-架构与核心概念" tabindex="-1">MCP 架构与核心概念 <a class="header-anchor" href="#mcp-架构与核心概念" aria-label="Permalink to &quot;MCP 架构与核心概念&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>说清楚 MCP 要解决的问题：为什么&quot;每个应用 × 每个工具&quot;各写一遍集成不可持续</li><li>区分 Host、Client、Server 三个角色，以及 Tools、Resources、Prompts 三类能力</li><li>理解 stdio 与 Streamable HTTP 两种传输方式的适用场景</li><li>能读懂一次完整的 MCP 会话：初始化、发现能力、调用工具</li></ul></div><h2 id="mcp-解决什么问题" tabindex="-1">MCP 解决什么问题 <a class="header-anchor" href="#mcp-解决什么问题" aria-label="Permalink to &quot;MCP 解决什么问题&quot;">​</a></h2><p>在 <a href="/guide/05-tool-calling/concept">工具调用原理</a> 里我们学过：模型本身只会&quot;说&quot;要调用哪个函数，真正执行的是你的应用代码。问题在于，每个应用都要自己写一遍&quot;查 GitHub&quot;&quot;读数据库&quot;&quot;搜文档&quot;的工具实现和 Schema。假设有 M 个 AI 应用（IDE 插件、桌面助手、自研 Agent）和 N 个外部系统，就要写 M × N 份集成代码。</p><p>MCP（Model Context Protocol）是 Anthropic 在 2024 年底开源的一个开放协议，目标就是把 M × N 变成 M + N：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>没有 MCP：每个应用自己对接每个系统           有了 MCP：大家都讲同一种协议</span></span>
<span class="line"><span></span></span>
<span class="line"><span> 应用A ──┬── GitHub                       应用A ─┐               ┌─ GitHub Server</span></span>
<span class="line"><span>         ├── 数据库                       应用B ─┼── MCP 协议 ──┼─ 数据库 Server</span></span>
<span class="line"><span>         └── 文件系统                     应用C ─┘               └─ 文件系统 Server</span></span>
<span class="line"><span> 应用B ──┬── GitHub</span></span>
<span class="line"><span>         ├── 数据库        （M × N）                    （M + N）</span></span>
<span class="line"><span>         └── ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>一个常见的类比是&quot;AI 应用的 USB-C 接口&quot;：工具提供方写一次 MCP Server，任何支持 MCP 的应用（Claude Desktop、Claude Code、Cursor、VS Code、你自己写的 Agent）都能直接用。</p><p>需要强调的是：<strong>MCP 并没有改变 Tool Calling 的本质</strong>。模型依然是通过 function calling 决定调用什么，MCP 只是标准化了&quot;工具从哪来、怎么描述、怎么调用&quot;这一层。</p><h2 id="三个角色-host、client、server" tabindex="-1">三个角色：Host、Client、Server <a class="header-anchor" href="#三个角色-host、client、server" aria-label="Permalink to &quot;三个角色：Host、Client、Server&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────── Host（如 Claude Desktop / 你的 Agent 应用）─────┐</span></span>
<span class="line"><span>│                                                                              │</span></span>
<span class="line"><span>│   ┌──────────┐      ┌──────────────┐                ┌───────────────────┐    │</span></span>
<span class="line"><span>│   │   LLM    │◀────▶│  Host 逻辑    │──▶ Client 1 ──▶│ Server: 文件系统  │    │</span></span>
<span class="line"><span>│   └──────────┘      │ (对话、权限、  │                └───────────────────┘    │</span></span>
<span class="line"><span>│                     │  工具路由)    │──▶ Client 2 ──▶┌───────────────────┐    │</span></span>
<span class="line"><span>│                     └──────────────┘                │ Server: GitHub     │    │</span></span>
<span class="line"><span>│                                                     └───────────────────┘    │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><table tabindex="0"><thead><tr><th>角色</th><th>是什么</th><th>职责</th></tr></thead><tbody><tr><td>Host</td><td>用户直接使用的 AI 应用</td><td>管理对话与模型调用；决定连接哪些 Server；负责授权和用户确认</td></tr><tr><td>Client</td><td>Host 内部的协议客户端</td><td>与<strong>一个</strong> Server 保持一对一连接，收发协议消息</td></tr><tr><td>Server</td><td>暴露能力的独立程序</td><td>提供工具、资源、提示词模板；可以是本地进程也可以是远程服务</td></tr></tbody></table><p>注意 Client 和 Server 是<strong>一对一</strong>的：Host 连了 3 个 Server，内部就有 3 个 Client 实例。这样每个 Server 的连接、权限、故障都彼此隔离。</p><h2 id="三类核心能力-tools、resources、prompts" tabindex="-1">三类核心能力：Tools、Resources、Prompts <a class="header-anchor" href="#三类核心能力-tools、resources、prompts" aria-label="Permalink to &quot;三类核心能力：Tools、Resources、Prompts&quot;">​</a></h2><p>Server 可以向 Client 暴露三类原语（primitive），区别在于&quot;谁来决定使用它&quot;：</p><table tabindex="0"><thead><tr><th>原语</th><th>控制方</th><th>类比</th><th>例子</th></tr></thead><tbody><tr><td>Tools</td><td>模型决定调用</td><td>POST 接口，可以有副作用</td><td><code>create_issue</code>、<code>run_sql</code>、<code>send_email</code></td></tr><tr><td>Resources</td><td>应用决定读取</td><td>GET 接口，只读数据</td><td><code>file:///logs/app.log</code>、<code>db://schema/users</code></td></tr><tr><td>Prompts</td><td>用户主动选择</td><td>可复用的提示词模板</td><td>&quot;代码审查&quot;、&quot;生成周报&quot; 模板</td></tr></tbody></table><ul><li><strong>Tools</strong> 是最常用的，几乎所有 MCP Server 都以工具为主。每个工具有 <code>name</code>、<code>description</code> 和 <code>inputSchema</code>（JSON Schema），和 OpenAI 的 function 定义几乎一一对应。</li><li><strong>Resources</strong> 用 URI 标识，由 Host 决定什么时候把内容放进上下文（比如用户在界面里 @ 了某个文件）。它和工具的区别是：资源是被动的数据，不由模型自主触发。</li><li><strong>Prompts</strong> 是 Server 提供的模板，通常在 Host 的界面里以斜杠命令等形式出现，由用户手动选用。</li></ul><p>除此之外，协议还定义了一些反向能力，即 Server 请求 Client：例如 <strong>Sampling</strong>（Server 请 Host 代为调用一次大模型）和 <strong>Elicitation</strong>（Server 请 Host 向用户追问信息）。这些属于进阶内容，不是每个 Host 都支持。</p><h2 id="底层协议-json-rpc-2-0" tabindex="-1">底层协议：JSON-RPC 2.0 <a class="header-anchor" href="#底层协议-json-rpc-2-0" aria-label="Permalink to &quot;底层协议：JSON-RPC 2.0&quot;">​</a></h2><p>MCP 的所有消息都是 JSON-RPC 2.0 格式，分三种：请求（有 <code>id</code>，需要响应）、响应（带同样的 <code>id</code>）、通知（没有 <code>id</code>，不需要响应）。</p><p>一次典型会话的消息流如下：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client                                         Server</span></span>
<span class="line"><span>  │── initialize (协议版本、客户端能力) ─────────▶│</span></span>
<span class="line"><span>  │◀──────────────── 结果 (服务端能力、名称版本) ──│</span></span>
<span class="line"><span>  │── notifications/initialized ────────────────▶│   握手完成</span></span>
<span class="line"><span>  │                                              │</span></span>
<span class="line"><span>  │── tools/list ───────────────────────────────▶│</span></span>
<span class="line"><span>  │◀──────────────────────────── 工具列表+Schema ──│   能力发现</span></span>
<span class="line"><span>  │                                              │</span></span>
<span class="line"><span>  │── tools/call {name, arguments} ─────────────▶│</span></span>
<span class="line"><span>  │◀──────────────────────────── 结果 content[] ──│   执行工具</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>以工具调用为例，请求长这样：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tools/call&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;get_weather&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;arguments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;city&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;杭州&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>响应：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;result&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;杭州：小雨，18°C&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;isError&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>两个细节值得记住：</p><ol><li>工具<strong>业务层面</strong>的失败（比如城市不存在）应返回 <code>isError: true</code> 的结果，让模型看到错误信息并自行调整；而<strong>协议层面</strong>的错误（方法不存在、参数格式错误）才用 JSON-RPC 的 <code>error</code> 字段。这和 <a href="/guide/05-tool-calling/error-handling">工具错误处理与重试</a> 中&quot;把错误当作观察结果返回给模型&quot;的思路一致。</li><li><code>content</code> 是数组，可以包含 <code>text</code>、<code>image</code> 等多种类型。较新的规范版本还支持 <code>structuredContent</code> 返回结构化数据。</li></ol><h2 id="两种传输方式-stdio-与-streamable-http" tabindex="-1">两种传输方式：stdio 与 Streamable HTTP <a class="header-anchor" href="#两种传输方式-stdio-与-streamable-http" aria-label="Permalink to &quot;两种传输方式：stdio 与 Streamable HTTP&quot;">​</a></h2><p>JSON-RPC 消息需要一个&quot;管道&quot;来传输，MCP 规范定义了两种标准传输：</p><table tabindex="0"><thead><tr><th>维度</th><th>stdio</th><th>Streamable HTTP</th></tr></thead><tbody><tr><td>运行方式</td><td>Host 把 Server 作为子进程启动</td><td>Server 是独立的 HTTP 服务</td></tr><tr><td>通信</td><td>通过子进程的 stdin / stdout 收发，每行一条 JSON</td><td>客户端 POST 到单一端点（如 <code>/mcp</code>），服务端可返回普通 JSON 或 SSE 流</td></tr><tr><td>部署</td><td>本地，跟随 Host 启停</td><td>本地或远程，可多用户共享</td></tr><tr><td>鉴权</td><td>继承本机用户权限，通常靠环境变量传密钥</td><td>需要自己做鉴权，规范推荐基于 OAuth 2.1</td></tr><tr><td>典型场景</td><td>文件系统、本地 Git、本地数据库</td><td>SaaS 服务、团队共享的内部工具</td></tr></tbody></table><p>stdio 有一个新手常踩的坑：<strong>stdout 是协议通道</strong>，Server 代码里任何 <code>print</code> 到 stdout 的调试信息都会破坏 JSON-RPC 消息流，日志必须写到 stderr。</p><p>早期规范还有一种&quot;HTTP + SSE&quot;双端点传输，已在 2025 年的规范修订中被 Streamable HTTP 取代。你在旧教程里看到 <code>/sse</code> 端点，就是这种旧方式；新项目建议直接用 Streamable HTTP。</p><h2 id="版本与生态" tabindex="-1">版本与生态 <a class="header-anchor" href="#版本与生态" aria-label="Permalink to &quot;版本与生态&quot;">​</a></h2><p>MCP 规范以日期作为版本号（例如 <code>2025-06-18</code>），在 <code>initialize</code> 握手时双方协商使用哪个版本。官方维护了多种语言的 SDK，包括 Python、TypeScript、Go、Java、Kotlin、C# 等。规范还在快速演进，本站内容以写作时的规范为准，细节请对照 <a href="https://modelcontextprotocol.io/specification" target="_blank" rel="noreferrer">官方规范</a>。</p><h2 id="mcp-与普通-tool-calling-的关系" tabindex="-1">MCP 与普通 Tool Calling 的关系 <a class="header-anchor" href="#mcp-与普通-tool-calling-的关系" aria-label="Permalink to &quot;MCP 与普通 Tool Calling 的关系&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>            ┌──────────── Host 应用 ────────────┐</span></span>
<span class="line"><span> 用户问题 ─▶ │ 1. tools/list 拿到 MCP 工具        │</span></span>
<span class="line"><span>            │ 2. 转成模型的 tools 参数 ──────────┼──▶ LLM（function calling）</span></span>
<span class="line"><span>            │ 3. 模型返回 tool_calls ◀───────────┼───</span></span>
<span class="line"><span>            │ 4. tools/call 转发给对应 Server    │──▶ MCP Server</span></span>
<span class="line"><span>            │ 5. 结果作为 tool 消息回传模型        │</span></span>
<span class="line"><span>            └───────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>也就是说，模型完全不知道 MCP 的存在，它看到的只是普通的工具列表。把 MCP 工具&quot;翻译&quot;成模型 API 能理解的格式，是 Host 的工作，我们会在 <a href="/guide/10-mcp/mcp-client">在应用中接入 MCP</a> 里亲手实现。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>以为 MCP 能让模型更聪明</strong>：MCP 只解决集成的标准化。工具描述写得差、工具太多导致模型选错，这些问题依旧存在，参考 <a href="/guide/05-tool-calling/tool-design">工具设计原则</a>。</li><li><strong>一次接入太多 Server</strong>：每个工具的 Schema 都会占用上下文 Token。接了 10 个 Server、上百个工具，模型的选择准确率和成本都会变差。按任务按需启用。</li><li><strong>stdio Server 往 stdout 打日志</strong>：直接导致连接失败或解析错误，日志一律写 stderr。</li><li><strong>盲目信任第三方 Server</strong>：MCP Server 是能在你机器上执行代码的程序，工具描述本身也可能藏有恶意指令。安装前要像审查依赖包一样审查它，详见 <a href="/guide/10-mcp/mcp-client">在应用中接入 MCP</a> 的安全部分。</li><li><strong>混淆 Resources 和 Tools</strong>：想让模型自主去查的数据，应该做成 Tool；Resource 需要 Host 主动支持，很多 Host 对它的支持并不完善。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><ol><li>Host 同时连接了 GitHub、Postgres、文件系统三个 MCP Server，Host 内部有几个 Client？为什么这样设计？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>3 个。Client 与 Server 是一对一关系，每个连接独立维护协议状态、能力协商结果和生命周期，一个 Server 崩溃或权限受限不会影响其他 Server。</p></details><ol start="2"><li>一个工具执行时发现&quot;用户 ID 不存在&quot;，应该返回 JSON-RPC <code>error</code> 还是 <code>isError: true</code> 的结果？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>返回 <code>isError: true</code> 的工具结果，并在 content 中写清错误原因。这是业务错误，模型需要看到它才能调整参数或告知用户。JSON-RPC <code>error</code> 留给协议层错误，比如调用了不存在的方法。</p></details><ol start="3"><li>你要把公司内部的工单系统做成 MCP Server 给全组几十人使用，选 stdio 还是 Streamable HTTP？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>Streamable HTTP 更合适：集中部署一份，便于统一鉴权（如接入公司 SSO / OAuth）、审计和升级。stdio 需要每个人在本地运行一份并各自配置凭证，难以管理。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">MCP 官方网站与文档</a></li><li><a href="https://modelcontextprotocol.io/specification" target="_blank" rel="noreferrer">MCP 规范</a></li><li><a href="https://github.com/modelcontextprotocol" target="_blank" rel="noreferrer">MCP GitHub 组织（各语言 SDK 与官方 Server 示例）</a></li><li>下一篇：<a href="/guide/10-mcp/mcp-server">开发一个 MCP Server</a></li><li>实战项目：<a href="/projects/05-mcp-server">05 开发自己的 MCP Server</a></li></ul>`,48)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
